<script setup lang="ts">
import PrototypePreview from './PrototypePreview.vue';
import {ref,onMounted,onUnmounted,computed,nextTick} from 'vue';import {useRoute} from 'vue-router';import {api,when} from './api';import {marked} from 'marked';import DOMPurify from 'dompurify';import Icon from './Icon.vue';
const route=useRoute(),token=route.path.split('/')[2],data=ref<any>(null),error=ref(''),comment=ref({author:'',content:''}),busy=ref(false),frame=ref<HTMLIFrameElement>();
const showReviews=ref(false),commentError=ref(''),commentNotice=ref(''),reviewPanel=ref<HTMLElement>(),reviewToggle=ref<HTMLButtonElement>();
async function toggleReviews(){showReviews.value=!showReviews.value;if(showReviews.value){await nextTick();reviewPanel.value?.focus();}else reviewToggle.value?.focus();}
function closeReviews(){showReviews.value=false;reviewToggle.value?.focus();}
const locked=ref(false),password=ref('');
async function unlock(){busy.value=true;error.value='';try{await api('/share/'+token+'/unlock','POST',{password:password.value});await load();locked.value=false;password.value='';}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
const html=computed(()=>DOMPurify.sanitize(marked.parse(data.value?.body.content||'') as string));
async function load(){data.value=await api('/share/'+token);}
async function send(){if(busy.value)return;busy.value=true;commentError.value='';commentNotice.value='';try{await api('/share/'+token+'/comments','POST',comment.value);comment.value.content='';commentNotice.value='评审意见已提交';try{await load();}catch{commentNotice.value='评审意见已提交，列表刷新失败，请刷新页面查看';}}catch(e:any){commentError.value=e.message;}finally{busy.value=false;}}
async function bridge(e:MessageEvent){if(e.source!==frame.value?.contentWindow||e.data?.type!=='pm-data')return;const {requestId,...body}=e.data;try{if(body.action!=='list')throw new Error('分享预览为只读数据，编辑成员可在项目内进行真实交互');const result=await api('/share/'+token+'/data','POST',body);frame.value?.contentWindow?.postMessage({type:'pm-data-result',requestId,result},'*');}catch(e:any){frame.value?.contentWindow?.postMessage({type:'pm-data-result',requestId,error:e.message},'*');}}
onMounted(async()=>{window.addEventListener('message',bridge);try{await load();}catch(e:any){if(e.status===403)locked.value=true;else error.value=e.message;}});onUnmounted(()=>window.removeEventListener('message',bridge));
</script><template><div class="share-page" :class="{'share-prototype-page':data?.kind==='prototype'}"><header><a href="/" class="brand"><img src="/favicon.svg" alt="序构"/><b>序构 <small>PRODUCT STUDIO</small></b></a><span class="badge">{{data?.role==='reviewer'?'团队评审':'只读分享'}}</span></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><form v-if="locked" class="share-password-card" @submit.prevent="unlock"><Icon name="Lock" :size="30"/><h1>此分享已设置访问密码</h1><p>输入分享者提供的密码即可查看，无需登录账号。</p><label>访问密码<input v-model="password" type="password" autocomplete="current-password" required maxlength="64" autofocus/></label><button class="primary" :disabled="busy">{{busy?'正在验证…':'查看分享'}}</button></form><template v-if="data"><div class="page-heading"><div><span class="eyebrow">SHARED FOR BETTER PRODUCTS</span><h1>{{data.title}}</h1><p>{{data.body.description||'在同一份上下文里，让讨论更有价值。'}} · v{{data.version}}</p></div><div class="share-preview-actions"><button ref="reviewToggle" class="secondary" :aria-expanded="showReviews" aria-controls="share-reviews" @click="toggleReviews"><Icon name="MessageSquare"/>{{showReviews?'收起评审':'评审意见'}}（{{data.comments.length}}）</button><button v-if="data.kind==='prototype'" class="secondary" @click="($el.querySelector('.prototype-player') as HTMLElement)?.requestFullscreen()"><Icon name="Maximize2"/>全屏演示</button></div></div><div class="share-layout share-review-layout"><section><PrototypePreview v-if="data.kind==='prototype'" :item="data" :share-token="token" standalone fluid-desktop/><div v-else v-html="html" class="markdown-body"></div></section><aside id="share-reviews" ref="reviewPanel" class="share-review-panel" v-show="showReviews" role="region" aria-label="评审意见面板" tabindex="-1" @keydown.esc.stop="closeReviews"><header><h3>评审意见 <span class="muted">{{data.comments.length}}</span></h3><button class="icon-button" aria-label="收起评论面板" @click="closeReviews"><Icon name="X"/></button></header><p v-if="data.role!=='reviewer'" class="review-permission">此链接仅可查看。需要填写评论，请联系分享者提供「可查看并评审」链接。</p><p v-if="commentError" class="error-inline" role="alert">{{commentError}}</p><p v-if="commentNotice" class="review-notice" role="status">{{commentNotice}}</p><form v-if="data.role==='reviewer'" @submit.prevent="send"><label>你的姓名<input v-model="comment.author" required maxlength="100"/></label><label>建议或问题<textarea v-model="comment.content" rows="4" required maxlength="10000"/></label><button class="primary" :disabled="busy">{{busy?'正在提交…':'提交评审意见'}}</button></form><article v-for="c in data.comments" class="comment-card"><strong>{{c.author}}</strong><span v-if="c.resolved" class="badge green">已解决</span><p>{{c.content}}</p><small>{{when(c.created_at)}}</small></article><div v-if="!data.comments.length" class="empty-mini">留下具体的建议，一起让产品更好。</div></aside></div></template></div></template>
